import axios from 'axios'
import useToast from './useToastService'
import useUserStore from '@/stores/user'
import useAppStore from '@/stores/app'

const toast = useToast()

const BASE_URL = import.meta.env.MODE === 'development' ? '/api' : ''

const request = axios.create({
  baseURL: BASE_URL,
  timeout: 0
})

let AppStore
const LanguageMap = {
  'zh-CN': 'cn',
  en: 'en'
}

request.interceptors.request.use(
  (config) => {
    const UserStore = useUserStore()
    if (!AppStore) {
      AppStore = useAppStore()
    }
    const token = UserStore.token
    const language = AppStore.language
    if (token) {
      config.headers['Authorization'] = `Bearer ${token}`
    }
    config.headers['Accept-Language'] = LanguageMap[language] || 'zh-CN'

    // 添加调试信息，检查请求数据
    if (config.url.includes('updateAssistant')) {
      console.log('发送到updateAssistant的请求配置:', config)
      console.log('请求数据:', config.data)
      if (typeof config.data === 'string') {
        console.log('请求数据(解析):', JSON.parse(config.data))
      }
    }

    return config
  },
  (error) => {
    Promise.reject(error)
  }
)

// error Handler
const errorHandler = (error) => {
  // const config = error.config
  toast.add({ severity: 'error', summary: 'ERROR', detail: error.errMsg, life: 3000 })
  if (error.response) {
    console.error(error.response.statusText, error.response.status)
  } else if (error.message) {
    console.error(error.message)
  }
  return Promise.reject(error)
}

// response interceptor
request.interceptors.response.use((response) => {
  if (response.headers['content-type'] === 'application/pdf' || response.headers['content-type'] === 'application/octet-stream') {
    return Promise.resolve(response.data)
  }
  if (!response.headers['content-type'].includes('application/json')) {
    return Promise.resolve(response)
  }
  const resData = response.data
  if (resData.flag) {
    // 接口返回成功状态
    return Promise.resolve(resData)
  } else {
    // 接口返回失败状态
    toast.add({ severity: 'error', summary: 'ERROR', detail: resData.errMsg, life: 3000 })
    console.error(resData.errMessage, resData.errCode)
    return Promise.reject(resData)
  }
}, errorHandler)

export default request
