import { createRouter, createWebHashHistory } from 'vue-router'

const router = createRouter({
  history: createWebHashHistory(import.meta.env.BASE_URL),
  routes: [
    {
      path: '/',
      redirect: '/chat',
      component: () => import('@/layouts/Main.vue'),
      children: [
        {
          path: 'chat',
          name: 'chat',
          component: () => import('@/views/chat/Chat.vue'),
          meta: { title: 'Chat', keepAlive: true }
        },
        {
          path: 'assistant',
          name: 'assistant',
          component: () => import('@/views/assistant/Index.vue'),
          meta: { title: 'Assistant' }
        },
        {
          path: 'agent',
          name: 'agent',
          component: () => import('@/views/agent/Agent.vue'),
          meta: { title: 'agent' }
        },
        {
          path: 'iframe',
          name: 'iframe',
          component: () => import('@/views/iframe/Index.vue'),
          meta: { title: 'IFrame' }
        },
        {
          path: 'setting',
          name: 'setting',
          component: () => import('@/views/setting/Setting.vue'),
          meta: { title: '设置' }
        },
        {
          path: 'knowledge',
          name: 'knowledge',
          component: () => import('@/views/knowledge/index.vue'),
          meta: { title: '知识库' }
        },
        {
          path: 'knowledge-detail',
          name: 'knowledgeDetail',
          component: () => import('@/views/knowledge/components/KnowledgeDetail.vue'),
          meta: { title: 'Knowledge Base Detail', activeName: 'knowledge' }
        },
        {
          path: 'translate',
          name: 'translate',
          component: () => import('@/views/translate/TranslateFile.vue'),
          meta: { title: '文档翻译' }
        }
      ]
    },
    // {
    //   path: '/login',
    //   name: 'login',
    //   component: () => import('@/views/login/Login.vue'),
    //   meta: { title: 'login' }
    // },
    { path: '/:pathMatch(.*)*', redirect: '/' }
  ]
})

export default router
