import request from '../hooks/useHttp'

export function getTempPath() {
  return request({
    method: 'get',
    url: '/setting/system/default/path'
  })
}

export function setTempPath(data) {
  return request({
    method: 'put',
    url: '/setting/system/path/update',
    data
  })
}

export function getMigrateProgress() {
  return request({
    method: 'get',
    url: '/setting/system/path/migrate/state'
  })
}

export function getApiServerStatus(params) {
  return request({
    method: 'get',
    url: '/openai/state',
    params
  })
}

export function startApiServer(params) {
  return request({
    method: 'get',
    url: `/openai/start/${params.port}`,
    params
  })
}

export function stopApiServer(params) {
  return request({
    method: 'get',
    url: '/openai/stop',
    params
  })
}

export function getVersion() {
  return request({
    method: 'get',
    url: '/setting/system/default/openchatversion'
  })
}
