import { createI18n } from 'vue-i18n'
import zhCN from './lang/zh-CN'
import en from './lang/en'
import kb_zhCN from './lang/zh-CN/knowledge'
import kb_EN from './lang/en/knowledge'
import assistant_zhCN from './lang/zh-CN/assistant'
import assistant_EN from './lang/en/assistant'

const messages = {
  'zh-CN': {
    lang: zhCN,
    kb: kb_zhCN,
    assistant: assistant_zhCN
  },
  en: {
    lang: en,
    kb: kb_EN,
    assistant: assistant_EN
  }
}

export const defaultLang = localStorage.getItem('lang') || 'zh-CN'

export const i18n = createI18n({
  locale: defaultLang,
  legacy: false,
  globalInjection: true,
  fallbackLocale: 'zh-CN',
  messages
})

export function i18nRender(key, params) {
  return i18n.global.t(key, params)
}
