import { defineStore } from 'pinia'
import { i18n, i18nRender } from '@/locales'
import {
  getTempPath as service_getTempPath,
  setTempPath as service_setTempPath,
  getApiServerStatus as service_getApiServerStatus,
  startApiServer as service_startApiServer,
  stopApiServer as service_stopApiServer
} from '@/services'
import { useDialog } from 'primevue/usedialog'

const useAppStore = defineStore('app', () => {
  function getLanguage() {
    return localStorage.getItem('lang') || 'zh-CN'
  }

  const language = ref(getLanguage())

  function setLanguage(lang) {
    language.value = lang
    i18n.global.locale.value = lang
    localStorage.setItem('lang', lang)
  }

  const conversationCollapsed = ref(false)
  const settingCollapsed = ref(true)

  function setConversationCollapsed(value) {
    conversationCollapsed.value = value
  }

  function setSettingCollapsed(value) {
    settingCollapsed.value = value
  }

  const tempPath = ref('')

  function setTempPath(value) {
    return service_setTempPath({ config_value: value }).then(async (res) => {
      return res.resData
    })
  }

  const dialog = useDialog()
  const Migrating = defineAsyncComponent(() => import('@/components/Migrating.vue'))

  function getTempPath() {
    return service_getTempPath().then((res) => {
      const { migrate_status } = res.resData
      if (migrate_status === 'MOVING') {
        const MigrateDialog = () => {
          dialog.open(Migrating, {
            props: {
              closable: false,
              modal: true,
              header: i18nRender('lang.migrate')
            }
          })
        }
        MigrateDialog()
        return res.resData
      }

      tempPath.value = res.resData.config_value
      return res.resData
    })
  }

  const theme = ref(localStorage.theme || 'light')

  function getTheme() {
    if (
      localStorage.theme === 'dark' ||
      ((!('theme' in localStorage) || localStorage.theme === 'system') && window.matchMedia('(prefers-color-scheme: dark)').matches)
    ) {
      document.documentElement.classList.add('dark')
    } else {
      document.documentElement.classList.remove('dark')
    }

    return theme.value
  }

  async function setTheme(_theme = 'light') {
    localStorage.theme = _theme
    theme.value = _theme
    getTheme()
  }

  function initTheme() {
    console.log('initTheme')
  }

  initTheme()

  const apiServerOpen = ref(false)
  const apiServerPort = ref(5051)

  function getApiServerStatus() {
    return service_getApiServerStatus().then(({ resData }) => {
      console.log(resData)
      apiServerOpen.value = resData.state
      apiServerPort.value = resData.port
    })
  }

  async function startApiServer(port = 5051) {
    return await service_startApiServer({ port }).then(() => {
      apiServerOpen.value = true
      apiServerPort.value = port
    })
  }

  async function stopApiServer() {
    return await service_stopApiServer().then(() => {
      apiServerOpen.value = false
    })
  }

  return {
    language,
    getLanguage,
    setLanguage,
    setConversationCollapsed,
    setSettingCollapsed,
    conversationCollapsed,
    settingCollapsed,
    tempPath,
    setTempPath,
    getTempPath,
    getTheme,
    setTheme,
    theme,
    apiServerOpen,
    apiServerPort,
    getApiServerStatus,
    startApiServer,
    stopApiServer
  }
})

export default useAppStore
